window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8bbbbd61d8bfed08"]={"versions": [{"id": "FIG-8bbbbd61d8bfed08", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0.001, max = 0.100, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code> und <code>COMM_BUS_TYPE_ETH</code>.</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMGlobalNvmBlockDescriptor</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Jeder Kommunikationskanal muss zwingend ein Netzwerkmanagement (<code>ComMNetworkManagement</code>, genau 1) und einen Bustyp (<code>ComMBusType</code>) besitzen. Die <code>ComMChannelId</code> dient als symbolischer Name im Bereich 0 bis 255. Das Metamodell schreibt die Wertebereiche und Defaultwerte für die Kanalinitialisierung strikt vor.</p>"}, {"id": "FIG-df1d9201ea1fd4de", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0.001, max = 0.100, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code>, <code>COMM_BUS_TYPE_ETH</code> und <code>COMM_BUS_TYPE_CDD</code>.</li>\n<li><code>ComMCDDBusPrefix</code> (<code>EcucStringParamDef</code>, Multiplizität 0..1).</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMGlobalNvmBlockDescriptor</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Neben Standardbussen (CAN, FR, LIN, ETH, INTERNAL) wird Complex Device Driver (<code>COMM_BUS_TYPE_CDD</code>) unterstützt, wofür optional das String-Präfix <code>ComMCDDBusPrefix</code> konfiguriert werden kann. Jeder Kommunikationskanal muss zwingend ein Netzwerkmanagement (<code>ComMNetworkManagement</code>, genau 1) und einen Bustyp (<code>ComMBusType</code>) besitzen. Die <code>ComMChannelId</code> dient als symbolischer Name im Bereich 0 bis 255. Das Metamodell schreibt die Wertebereiche und Defaultwerte für die Kanalinitialisierung strikt vor.</p>"}, {"id": "FIG-0b815b16baa18e39", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0.001, max = 0.100, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code>, <code>COMM_BUS_TYPE_ETH</code> und <code>COMM_BUS_TYPE_CDD</code>.</li>\n<li><code>ComMCDDBusPrefix</code> (<code>EcucStringParamDef</code>, Multiplizität 0..1).</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoWakeUpInhibitionNvmStorage</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Die maximale Kanalanzahl ist auf 256 (<code>ComMChannel</code>, 1..256) und die Anzahl der Benutzer pro Kanal auf maximal 255 (<code>ComMUserPerChannel</code>, 0..255) begrenzt. Für die nichtflüchtige Speicherung von Weckinhibitions-Zuständen steht der Parameter <code>ComMNoWakeUpInhibitionNvmStorage</code> zur Verfügung. Neben Standardbussen (CAN, FR, LIN, ETH, INTERNAL) wird Complex Device Driver (<code>COMM_BUS_TYPE_CDD</code>) unterstützt, wofür optional das String-Präfix <code>ComMCDDBusPrefix</code> konfiguriert werden kann. Jeder Kanal besitzt genau ein <code>ComMNetworkManagement</code>. Die <code>ComMChannelId</code> dient als symbolischer Name im Bereich 0 bis 255.</p>"}, {"id": "FIG-eaf83f85eccd1689", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0, max = INF, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code>, <code>COMM_BUS_TYPE_ETH</code> und <code>COMM_BUS_TYPE_CDD</code>.</li>\n<li><code>ComMCDDBusPrefix</code> (<code>EcucStringParamDef</code>, Multiplizität 0..1).</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoWakeUpInhibitionNvmStorage</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Die Begrenzung der Periodendauer <code>ComMMainFunctionPeriod</code> ist formal für <code>min = 0</code> und <code>max = INF</code> definiert (Standardwert 0.020 s). Die maximale Kanalanzahl ist auf 256 (<code>ComMChannel</code>, 1..256) und die Anzahl der Benutzer pro Kanal auf maximal 255 (<code>ComMUserPerChannel</code>, 0..255) begrenzt. Für die nichtflüchtige Speicherung von Weckinhibitions-Zuständen steht der Parameter <code>ComMNoWakeUpInhibitionNvmStorage</code> zur Verfügung. Neben Standardbussen (CAN, FR, LIN, ETH, INTERNAL) wird Complex Device Driver (<code>COMM_BUS_TYPE_CDD</code>) unterstützt, wofür optional das String-Präfix <code>ComMCDDBusPrefix</code> konfiguriert werden kann. Jeder Kanal besitzt genau ein <code>ComMNetworkManagement</code>. Die <code>ComMChannelId</code> dient als symbolischer Name im Bereich 0 bis 255.</p>"}, {"id": "FIG-4e198e606eb4141c", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0, max = INF, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code>, <code>COMM_BUS_TYPE_ETH</code> und <code>COMM_BUS_TYPE_CDD</code>.</li>\n<li><code>ComMCDDBusPrefix</code> (<code>EcucStringParamDef</code>, Multiplizität 0..1).</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoWakeUpInhibitionNvmStorage</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Die Begrenzung der Periodendauer <code>ComMMainFunctionPeriod</code> ist formal für <code>min = 0</code> und <code>max = INF</code> definiert (Standardwert 0.020 s). Die maximale Kanalanzahl ist auf 256 (<code>ComMChannel</code>, 1..256) und die Anzahl der Benutzer pro Kanal auf maximal 255 (<code>ComMUserPerChannel</code>, 0..255) begrenzt. Für die nichtflüchtige Speicherung von Weckinhibitions-Zuständen steht der Parameter <code>ComMNoWakeUpInhibitionNvmStorage</code> zur Verfügung. Neben Standardbussen (CAN, FR, LIN, ETH, INTERNAL) wird Complex Device Driver (<code>COMM_BUS_TYPE_CDD</code>) unterstützt, wofür optional das String-Präfix <code>ComMCDDBusPrefix</code> konfiguriert werden kann. Jeder Kanal besitzt genau ein <code>ComMNetworkManagement</code>. Die <code>ComMChannelId</code> dient als symbolischer Name im Bereich 0 bis 255.</p>"}, {"id": "FIG-f939660fb4af70a1", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0, max = INF, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code>, <code>COMM_BUS_TYPE_ETH</code> und <code>COMM_BUS_TYPE_CDD</code>.</li>\n<li><code>ComMCDDBusPrefix</code> (<code>EcucStringParamDef</code>, Multiplizität 0..1).</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoWakeUpInhibitionNvmStorage</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): defaultValue = COMM_GATEWAY_TYPE_ACTIVE, Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<p class=\"fig-p\">Über die Referenzbeziehung <code>+reference</code> referenziert <code>ComMChannel</code>:</p>\n<ul class=\"fig-list\">\n<li><code>ComMChannelPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1) mit dem Ziel (<code>+destination</code>) <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Für Multicore- oder partitionierte Systeme erlaubt die Referenz <code>ComMChannelPartitionRef</code> die optionale Zuordnung eines Kommunikationskanals zu einer <code>EcucPartition</code>. Der Parameter <code>ComMPncGatewayType</code> besitzt den Standardwert <code>COMM_GATEWAY_TYPE_ACTIVE</code>. Die Begrenzung der Periodendauer <code>ComMMainFunctionPeriod</code> ist formal für <code>min = 0</code> und <code>max = INF</code> definiert (Standardwert 0.020 s). Die maximale Kanalanzahl beträgt 256 (<code>ComMChannel</code>, 1..256), Benutzer pro Kanal maximal 255 (<code>ComMUserPerChannel</code>, 0..255). Neben Standardbussen (CAN, FR, LIN, ETH, INTERNAL) wird Complex Device Driver (<code>COMM_BUS_TYPE_CDD</code>) unterstützt. Jeder Kanal besitzt genau ein <code>ComMNetworkManagement</code>.</p>"}, {"id": "FIG-71054701493b7adf", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0, max = INF, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code>, <code>COMM_BUS_TYPE_ETH</code> und <code>COMM_BUS_TYPE_CDD</code>.</li>\n<li><code>ComMCDDBusPrefix</code> (<code>EcucStringParamDef</code>, Multiplizität 0..1).</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoWakeUpInhibitionNvmStorage</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): defaultValue = COMM_GATEWAY_TYPE_ACTIVE, Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n<li><code>ComMWakeupSleepRequestEnabled</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1): defaultValue = false.</li>\n<li><code>ComMDynamicPncToChannelMappingEnabled</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1): defaultValue = false.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<p class=\"fig-p\">Über die Referenzbeziehung <code>+reference</code> referenziert <code>ComMChannel</code>:</p>\n<ul class=\"fig-list\">\n<li><code>ComMChannelPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1) mit dem Ziel (<code>+destination</code>) <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Zur Steuerung erweiterter Kanalfeatures stehen <code>ComMWakeupSleepRequestEnabled</code> (Aktivierung von Wakeup/Sleep-Requests) und <code>ComMDynamicPncToChannelMappingEnabled</code> (Aktivierung dynamischer PNC-zu-Kanal-Zuordnung) als optionale Boolean-Parameter mit Defaultwert <code>false</code> zur Verfügung. Für Multicore- oder partitionierte Systeme erlaubt die Referenz <code>ComMChannelPartitionRef</code> die optionale Zuordnung eines Kommunikationskanals zu einer <code>EcucPartition</code>. Der Parameter <code>ComMPncGatewayType</code> besitzt den Standardwert <code>COMM_GATEWAY_TYPE_ACTIVE</code>. Die Begrenzung der Periodendauer <code>ComMMainFunctionPeriod</code> ist formal für <code>min = 0</code> und <code>max = INF</code> definiert (Standardwert 0.020 s). Die maximale Kanalanzahl beträgt 256 (<code>ComMChannel</code>, 1..256), Benutzer pro Kanal maximal 255 (<code>ComMUserPerChannel</code>, 0..255). Neben Standardbussen (CAN, FR, LIN, ETH, INTERNAL) wird Complex Device Driver (<code>COMM_BUS_TYPE_CDD</code>) unterstützt. Jeder Kanal besitzt genau ein <code>ComMNetworkManagement</code>.</p>"}, {"id": "FIG-3d33d05a6ba62e65", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0, max = INF, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code>, <code>COMM_BUS_TYPE_ETH</code> und <code>COMM_BUS_TYPE_CDD</code>.</li>\n<li><code>ComMCDDBusPrefix</code> (<code>EcucStringParamDef</code>, Multiplizität 0..1).</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoWakeUpInhibitionNvmStorage</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): defaultValue = COMM_GATEWAY_TYPE_ACTIVE, Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n<li><code>ComMWakeupSleepRequestEnabled</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1): defaultValue = false.</li>\n<li><code>ComMDynamicPncToChannelMappingEnabled</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1): defaultValue = false.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<p class=\"fig-p\">Über die Referenzbeziehung <code>+reference</code> referenziert <code>ComMChannel</code>:</p>\n<ul class=\"fig-list\">\n<li><code>ComMChannelPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1) mit dem Ziel (<code>+destination</code>) <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Zur Steuerung erweiterter Kanalfeatures stehen <code>ComMWakeupSleepRequestEnabled</code> (Aktivierung von Wakeup/Sleep-Requests) und <code>ComMDynamicPncToChannelMappingEnabled</code> (Aktivierung dynamischer PNC-zu-Kanal-Zuordnung) als optionale Boolean-Parameter mit Defaultwert <code>false</code> zur Verfügung. Für Multicore- oder partitionierte Systeme erlaubt die Referenz <code>ComMChannelPartitionRef</code> die optionale Zuordnung eines Kommunikationskanals zu einer <code>EcucPartition</code>. Der Parameter <code>ComMPncGatewayType</code> besitzt den Standardwert <code>COMM_GATEWAY_TYPE_ACTIVE</code>. Die Begrenzung der Periodendauer <code>ComMMainFunctionPeriod</code> ist formal für <code>min = 0</code> und <code>max = INF</code> definiert (Standardwert 0.020 s). Die maximale Kanalanzahl beträgt 256 (<code>ComMChannel</code>, 1..256), Benutzer pro Kanal maximal 255 (<code>ComMUserPerChannel</code>, 0..255). Neben Standardbussen (CAN, FR, LIN, ETH, INTERNAL) wird Complex Device Driver (<code>COMM_BUS_TYPE_CDD</code>) unterstützt. Jeder Kanal besitzt genau ein <code>ComMNetworkManagement</code>.</p>"}, {"id": "FIG-290ecfabcd9eac07", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0, max = INF, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, withAuto = true, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code>, <code>COMM_BUS_TYPE_ETH</code> und <code>COMM_BUS_TYPE_CDD</code>.</li>\n<li><code>ComMCDDBusPrefix</code> (<code>EcucStringParamDef</code>, Multiplizität 0..1).</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoWakeUpInhibitionNvmStorage</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): defaultValue = COMM_GATEWAY_TYPE_ACTIVE, Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n<li><code>ComMWakeupSleepRequestEnabled</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1): defaultValue = false.</li>\n<li><code>ComMDynamicPncToChannelMappingEnabled</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1): defaultValue = false.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<p class=\"fig-p\">Über die Referenzbeziehung <code>+reference</code> referenziert <code>ComMChannel</code>:</p>\n<ul class=\"fig-list\">\n<li><code>ComMChannelPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1) mit dem Ziel (<code>+destination</code>) <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Zur Steuerung erweiterter Kanalfeatures stehen <code>ComMWakeupSleepRequestEnabled</code> (Aktivierung von Wakeup/Sleep-Requests) und <code>ComMDynamicPncToChannelMappingEnabled</code> (Aktivierung dynamischer PNC-zu-Kanal-Zuordnung) als optionale Boolean-Parameter mit Defaultwert <code>false</code> zur Verfügung. Für Multicore- oder partitionierte Systeme erlaubt die Referenz <code>ComMChannelPartitionRef</code> die optionale Zuordnung eines Kommunikationskanals zu einer <code>EcucPartition</code>. Der Parameter <code>ComMPncGatewayType</code> besitzt den Standardwert <code>COMM_GATEWAY_TYPE_ACTIVE</code>. Die Begrenzung der Periodendauer <code>ComMMainFunctionPeriod</code> ist formal für <code>min = 0</code> und <code>max = INF</code> definiert (Standardwert 0.020 s). Die maximale Kanalanzahl beträgt 256 (<code>ComMChannel</code>, 1..256), Benutzer pro Kanal maximal 255 (<code>ComMUserPerChannel</code>, 0..255). Der Parameter <code>ComMChannelId</code> unterstützt über <code>withAuto = true</code> eine automatische Vergabe von Kanal-Identifikatoren durch Konfigurations- und Generierungswerkzeuge. Neben Standardbussen (CAN, FR, LIN, ETH, INTERNAL) wird über <code>COMM_BUS_TYPE_CDD</code> und das Präfix <code>ComMCDDBusPrefix</code> auch ein Complex Device Driver als Busanbindung unterstützt.</p>"}, {"id": "FIG-4a7b9a75517407e9", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0, max = INF, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, withAuto = true, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code>, <code>COMM_BUS_TYPE_ETH</code> und <code>COMM_BUS_TYPE_CDD</code>.</li>\n<li><code>ComMCDDBusPrefix</code> (<code>EcucStringParamDef</code>, Multiplizität 0..1).</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoWakeUpInhibitionNvmStorage</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): defaultValue = COMM_GATEWAY_TYPE_ACTIVE, Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n<li><code>ComMWakeupSleepRequestEnabled</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1): defaultValue = false.</li>\n<li><code>ComMDynamicPncToChannelMappingEnabled</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1): defaultValue = false.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<p class=\"fig-p\">Über die Referenzbeziehung <code>+reference</code> referenziert <code>ComMChannel</code>:</p>\n<ul class=\"fig-list\">\n<li><code>ComMChannelPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1) mit dem Ziel (<code>+destination</code>) <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Zur Steuerung erweiterter Kanalfeatures stehen <code>ComMWakeupSleepRequestEnabled</code> (Aktivierung von Wakeup/Sleep-Requests) und <code>ComMDynamicPncToChannelMappingEnabled</code> (Aktivierung dynamischer PNC-zu-Kanal-Zuordnung) als optionale Boolean-Parameter mit Defaultwert <code>false</code> zur Verfügung. Für Multicore- oder partitionierte Systeme erlaubt die Referenz <code>ComMChannelPartitionRef</code> die optionale Zuordnung eines Kommunikationskanals zu einer <code>EcucPartition</code>. Der Parameter <code>ComMPncGatewayType</code> besitzt den Standardwert <code>COMM_GATEWAY_TYPE_ACTIVE</code>. Die Begrenzung der Periodendauer <code>ComMMainFunctionPeriod</code> ist formal für <code>min = 0</code> und <code>max = INF</code> definiert (Standardwert 0.020 s). Die maximale Kanalanzahl beträgt 256 (<code>ComMChannel</code>, 1..256), Benutzer pro Kanal maximal 255 (<code>ComMUserPerChannel</code>, 0..255). Der Parameter <code>ComMChannelId</code> unterstützt über <code>withAuto = true</code> eine automatische Vergabe von Kanal-Identifikatoren durch Konfigurations- und Generierungswerkzeuge. Neben Standardbussen (CAN, FR, LIN, ETH, INTERNAL) wird über <code>COMM_BUS_TYPE_CDD</code> und das Präfix <code>ComMCDDBusPrefix</code> auch ein Complex Device Driver als Busanbindung unterstützt.</p>"}, {"id": "FIG-5806776c9a384a4c", "releases": ["R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Configuration) für den Communication Manager (<code>ComMChannel</code>). Es spezifiziert die strukturellen Parameter, Enumerationen, Container-Beziehungen und Kardinalitäten der Kommunikationskanalkonfiguration innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).</p>\n<p class=\"fig-p\">Er enthält folgende Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>): min = 0, max = INF, defaultValue = 0.020.</li>\n<li><code>ComMChannelId</code> (<code>EcucIntegerParamDef</code>): min = 0, max = 255, symbolicNameValue = true.</li>\n<li><code>ComMBusType</code> (<code>EcucEnumerationParamDef</code>): Enumeration mit den Literalen (<code>+literal</code>) <code>COMM_BUS_TYPE_CAN</code>, <code>COMM_BUS_TYPE_FR</code>, <code>COMM_BUS_TYPE_INTERNAL</code>, <code>COMM_BUS_TYPE_LIN</code>, <code>COMM_BUS_TYPE_ETH</code> und <code>COMM_BUS_TYPE_CDD</code>.</li>\n<li><code>ComMCDDBusPrefix</code> (<code>EcucStringParamDef</code>, Multiplizität 0..1).</li>\n<li><code>ComMNoWakeup</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoCom</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMFullCommRequestNotificationEnabled</code> (<code>EcucBooleanParamDef</code>): defaultValue = false.</li>\n<li><code>ComMNoWakeUpInhibitionNvmStorage</code> (<code>EcucBooleanParamDef</code>).</li>\n<li><code>ComMPncGatewayType</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 0..1): defaultValue = COMM_GATEWAY_TYPE_ACTIVE, Literale <code>COMM_GATEWAY_TYPE_ACTIVE</code> und <code>COMM_GATEWAY_TYPE_PASSIVE</code>.</li>\n<li><code>ComMWakeupSleepRequestEnabled</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1): defaultValue = false.</li>\n<li><code>ComMDynamicPncToChannelMappingEnabled</code> (<code>EcucBooleanParamDef</code>, Multiplizität 0..1): defaultValue = false.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich aggregiert <code>ComMChannel</code> folgende Subcontainer (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\">\n<li><code>ComMUserPerChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).</li>\n<li><code>ComMNetworkManagement</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1).</li>\n</ul>\n<p class=\"fig-p\">Über die Referenzbeziehung <code>+reference</code> referenziert <code>ComMChannel</code>:</p>\n<ul class=\"fig-list\">\n<li><code>ComMChannelPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1) mit dem Ziel (<code>+destination</code>) <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die definierten Attribute bestimmen das statische Verhalten des Communication Managers zur Generierungs- und Initialisierungszeit (z. B. Zykluszeit der Hauptfunktion <code>ComM_MainFunction_&lt;channel&gt;</code>, Zuweisung von Kanal-IDs und Busprotokolltypen).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-BSRT- und Codegeneratoren. Zur Steuerung erweiterter Kanalfeatures stehen <code>ComMWakeupSleepRequestEnabled</code> (Aktivierung von Wakeup/Sleep-Requests) und <code>ComMDynamicPncToChannelMappingEnabled</code> (Aktivierung dynamischer PNC-zu-Kanal-Zuordnung) als optionale Boolean-Parameter mit Defaultwert <code>false</code> zur Verfügung. Für Multicore- oder partitionierte Systeme erlaubt die Referenz <code>ComMChannelPartitionRef</code> die optionale Zuordnung eines Kommunikationskanals zu einer <code>EcucPartition</code>. Der Parameter <code>ComMPncGatewayType</code> besitzt den Standardwert <code>COMM_GATEWAY_TYPE_ACTIVE</code>. Die Begrenzung der Periodendauer <code>ComMMainFunctionPeriod</code> ist formal für <code>min = 0</code> und <code>max = INF</code> definiert (Standardwert 0.020 s). Die maximale Kanalanzahl beträgt 256 (<code>ComMChannel</code>, 1..256), Benutzer pro Kanal maximal 255 (<code>ComMUserPerChannel</code>, 0..255). Neben Standardbussen (CAN, FR, LIN, ETH, INTERNAL) wird Complex Device Driver (<code>COMM_BUS_TYPE_CDD</code>) unterstützt. Jeder Kanal besitzt genau ein <code>ComMNetworkManagement</code>.</p>"}], "trans": [{"from": "FIG-8bbbbd61d8bfed08", "to": "FIG-df1d9201ea1fd4de", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ComMBusType</code>: Neues Literal <code>COMM_BUS_TYPE_CDD:EcucEnumerationLiteralDef</code> hinzugefügt.</li>\n<li><code>ComMCDDBusPrefix</code>: Neuer Konfigurationsparameter vom Typ <code>EcucStringParamDef</code> hinzugefügt (Kardinalität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).</li>\n</ul>"}, {"from": "FIG-df1d9201ea1fd4de", "to": "FIG-0b815b16baa18e39", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ComMChannel</code>: Obere Multiplizität von <code>*</code> auf <code>256</code> geändert (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 256</code>).</li>\n<li><code>ComMUserPerChannel</code>: Obere Multiplizität von <code>*</code> auf <code>255</code> geändert (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 255</code>).</li>\n<li>Parameter <code>ComMGlobalNvmBlockDescriptor</code> entfernt und durch <code>ComMNoWakeUpInhibitionNvmStorage: EcucBooleanParamDef</code> ersetzt.</li>\n</ul>"}, {"from": "FIG-0b815b16baa18e39", "to": "FIG-eaf83f85eccd1689", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ComMMainFunctionPeriod</code>: Wertebereich für <code>min</code> von <code>0.001</code> auf <code>0</code> und für <code>max</code> von <code>0.100</code> auf <code>INF</code> geändert.</li>\n</ul>"}, {"from": "FIG-eaf83f85eccd1689", "to": "FIG-4e198e606eb4141c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Redaktionelle Anpassung der Formatierung: Leerzeichen vor Doppelpunkten in Elementbezeichnern vereinheitlicht (z. B. <code>ComMChannel:</code> statt <code>ComMChannel :</code>). Layout und Inhalt bleiben ansonsten unverändert.</li>\n</ul>"}, {"from": "FIG-4e198e606eb4141c", "to": "FIG-f939660fb4af70a1", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ComMPncGatewayType</code>: Defaultwert <code>defaultValue = COMM_GATEWAY_TYPE_ACTIVE</code> ergänzt.</li>\n<li><code>ComMChannelPartitionRef</code>: Neue Konfigurationsreferenz vom Typ <code>EcucReferenceDef</code> (<code>+reference</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) auf Zielcontainer <code>EcucPartition: EcucParamConfContainerDef</code> (<code>+destination</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>) hinzugefügt.</li>\n</ul>"}, {"from": "FIG-f939660fb4af70a1", "to": "FIG-71054701493b7adf", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ComMWakeupSleepRequestEnabled</code>: Neuer Konfigurationsparameter vom Typ <code>EcucBooleanParamDef</code> hinzugefügt (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, <code>defaultValue = false</code>).</li>\n<li><code>ComMDynamicPncToChannelMappingEnabled</code>: Neuer Konfigurationsparameter vom Typ <code>EcucBooleanParamDef</code> hinzugefügt (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, <code>defaultValue = false</code>).</li>\n</ul>"}, {"from": "FIG-71054701493b7adf", "to": "FIG-3d33d05a6ba62e65", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3d33d05a6ba62e65", "to": "FIG-5806776c9a384a4c", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5806776c9a384a4c", "to": "FIG-290ecfabcd9eac07", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Parameter <code>ComMChannelId</code>: Eigenschaft <code>withAuto = true</code> ergänzt; Reihenfolge der Attribute im Parameterkasten neu strukturiert (<code>min = 0</code>, <code>max = 255</code>, <code>withAuto = true</code>, <code>symbolicNameValue = true</code>).</li>\n</ul>"}, {"from": "FIG-290ecfabcd9eac07", "to": "FIG-4a7b9a75517407e9", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Enumerationsliteral <code>COMM_BUS_TYPE_INTERNAL</code>: Zeilenumbruch vor <code>EcucEnumerationLiteralDef</code> eingefügt (zweizeilige Darstellung statt einzeilig).</li>\n</ul>"}]};
